"pkglib.installAll.what": "“ติดตั้งทั้งหมด” คืออะไร?",
"pkglib.installAll.whatBody": "“ติดตั้งทั้งหมด” จะดำเนินการกับทุกแพ็กเกจที่พร้อมตามลำดับ: เกมหลัก → อัปเดต → DLC หากคุณมีอัปเดตเวอร์ชันเดียวกันสองรายการ (หรือ DLC สองชุดที่ขัดแย้งกัน) ให้ใช้ช่องทำเครื่องหมายในแต่ละแถวเพื่อเลือกว่าเครื่องนี้ควรติดตั้งรายการใด — กลุ่มละหนึ่งรายการเท่านั้น เอาเครื่องหมายออกเพื่อข้ามกลุ่มนั้น ส่วนปุ่มติดตั้งในแต่ละแถวจะติดตั้งเฉพาะแพ็กเกจนั้นเสมอ",
"pkglib.variants.title": "เลือกแพ็กเกจรุ่นย่อยของเวอร์ชันเดียวกันหนึ่งรายการ",
"pkglib.variants.body": "แพตช์/DLC รุ่นย่อยที่เตรียมไว้ {n} รายการ มุ่งไปยังเกมและเวอร์ชันเดียวกัน ระบบจะเก็บไว้ทั้งหมด แต่ PS5 คงแพตช์ที่ใช้งานอยู่ได้เพียงหนึ่งรายการต่อเวอร์ชันนั้น “ติดตั้งทั้งหมด” จะข้ามรายการเหล่านี้ กรุณาติดตั้ง Optional Fix หรือ Backport ที่ตรงกับเครื่องนี้จากแถวของรายการนั้น",
